from pathlib import Path
import json,sys,traceback
from playwright.sync_api import sync_playwright,expect
from book_test_helpers import seed,go,fixture,records,value,fail,BASE
OUT=Path(__file__).resolve().parent/('evidence/baseline' if '--baseline' in sys.argv else 'evidence/current')
def switch(p,template):
 if p.url.split('?')[0].endswith('m08-p09.html'):p.locator('#changeTemplate').click()
 else:p.get_by_role('button',name='保留草稿换模板',exact=True).click()
 p.wait_for_url('**/m08-p08.html*');expect(p.locator('[data-template="章节扉页"]')).to_be_disabled();p.locator('[data-template="'+template+'"]').click();p.locator('.use').click()
def diary_roundtrip(p):
 seed(p,books=[fixture()],records=records());go(p,9,'?id=book-state&page=page-state');p.locator('#excerpt').fill('跨模板保留的正文');p.locator('#page-title').fill('跨模板书页标题');p.locator('#message').fill('这一页的寄语');switch(p,'照片故事');p.wait_for_url('**/m08-p10.html*');expect(p.locator('.caption')).to_have_value('跨模板保留的正文');switch(p,'日记摘录');p.wait_for_url('**/m08-p09.html*');expect(p.locator('#excerpt')).to_have_value('跨模板保留的正文');expect(p.locator('#message')).to_have_value('这一页的寄语');p.locator('.done').click();p.wait_for_url('**/m08-p13.html*');saved=value(p)[0];assert len(saved['pages'])==1 and saved['pages'][0]['id']=='page-state' and saved['pages'][0]['title']=='跨模板书页标题';assert p.evaluate("JSON.parse(sessionStorage.getItem('dujia-prototype-book-editor')||'{}')")=={}
def photo_roundtrip(p):
 b=fixture();photo=dict(id='photo-source',type='photo',title='实际照片',date='2026-10-04',visibility='shared',status='published',image='data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" width="10" height="10"><rect width="10" height="10" fill="pink"/></svg>');b['pages'][0].update(template='照片故事',source=dict(kind='photo',id='photo-source'),photos=[dict(source=dict(kind='photo',id='photo-source'),crop=dict(x=25,y=60,zoom=1.5))],stickers=['⭐']);seed(p,books=[b],records=records()+[photo]);go(p,10,'?id=book-state&page=page-state');p.locator('.caption').fill('照片页的新想法');switch(p,'日记摘录');p.wait_for_url('**/m08-p09.html*');expect(p.locator('#excerpt')).to_have_value('照片页的新想法');switch(p,'照片故事');p.wait_for_url('**/m08-p10.html*');expect(p.locator('.caption')).to_have_value('照片页的新想法');expect(p.locator('.book-stickers')).to_have_text('⭐');assert p.locator('.book-photo-preview img').evaluate("e=>e.style.transform")=='scale(1.5)';fail(p,'book-page');p.locator('.done').click();expect(p.locator('.prototype-toast')).to_contain_text('未完成');assert value(p)[0]['pages'][0].get('body') is None;p.locator('.done').click();p.wait_for_url('**/m08-p13.html*');saved=value(p)[0]['pages'][0];assert saved['body']=='照片页的新想法' and saved['photos'][0]['crop']==dict(x=25,y=60,zoom=1.5) and saved['stickers']==['⭐']
def failed_stash_discard(p):
 seed(p,books=[fixture()],records=records());go(p,9,'?id=book-state&page=page-state');p.locator('#excerpt').fill('等待保留的草稿');fail(p,'book-editor-stash');p.locator('#changeTemplate').click();expect(p.locator('.prototype-toast')).to_contain_text('草稿未保留');assert 'm08-p09' in p.url;expect(p.locator('#excerpt')).to_have_value('等待保留的草稿');switch(p,'日记摘录');p.wait_for_url('**/m08-p09.html*');p.locator('.back').click();p.get_by_role('button',name='继续编辑',exact=True).click();expect(p.locator('dialog[open]')).to_have_count(0);expect(p.locator('#excerpt')).to_have_value('等待保留的草稿');p.locator('.back').click();p.get_by_role('button',name='放弃修改',exact=True).click();p.wait_for_url('**/m08-p08.html*');assert p.evaluate("JSON.parse(sessionStorage.getItem('dujia-prototype-book-editor')||'{}')")=={}
def conflict(p):
 seed(p,books=[fixture()],records=records());go(p,9,'?id=book-state&page=page-state');p.locator('#excerpt').fill('本地跨模板修改');switch(p,'日记摘录');p.wait_for_url('**/m08-p09.html*');other=p.context.new_page();other.goto(BASE+'prototype/review.html');other.evaluate("()=>{const rows=JSON.parse(localStorage.getItem('dujia-prototype-books'));rows[0].pages[0].body='另一窗口的新正文';localStorage.setItem('dujia-prototype-books',JSON.stringify(rows));}");p.locator('.done').click();expect(p.locator('.prototype-toast')).to_contain_text('书页已在另一处更新');expect(p.locator('#excerpt')).to_have_value('本地跨模板修改');assert value(p)[0]['pages'][0]['body']=='另一窗口的新正文';other.close()
def new_page_and_stale_route(p):
 b=fixture();b['pages']=[];seed(p,books=[b],records=records());go(p,9,'?id=book-state&source=source-state&kind=diary');p.locator('#excerpt').fill('新页草稿');switch(p,'日记摘录');p.wait_for_url('**/m08-p09.html*');draft_id=p.evaluate("new URLSearchParams(location.search).get('page')");p.locator('.done').click();p.wait_for_url('**/m08-p13.html*');assert len(value(p)[0]['pages'])==1 and value(p)[0]['pages'][0]['id']==draft_id;p.evaluate("()=>{const rows=JSON.parse(localStorage.getItem('dujia-prototype-books'));rows[0].pages=[];localStorage.setItem('dujia-prototype-books',JSON.stringify(rows));}");go(p,9,'?id=book-state&page='+draft_id);p.wait_for_url('**/m08-p13.html*');assert not value(p)[0]['pages'];go(p,9,'?id=book-state&source=source-state&kind=diary');p.locator('#excerpt').fill('即将放弃的新页');switch(p,'日记摘录');p.wait_for_url('**/m08-p09.html*');p.locator('.back').click();p.get_by_role('button',name='放弃修改',exact=True).click();p.wait_for_url('**/m08-p08.html*');p.locator('.use').click();p.wait_for_url('**/m08-p09.html*');p.locator('#excerpt').fill('放弃之后重新写的新页');p.locator('.done').click();p.wait_for_url('**/m08-p13.html*');assert len(value(p)[0]['pages'])==1 and value(p)[0]['pages'][0]['body']=='放弃之后重新写的新页'
def specialist_roundtrip_and_isolation(p):
 seed(p,books=[fixture(),fixture('other-book')],records=records());p.evaluate("localStorage.setItem('dujia-prototype-moments',JSON.stringify([{id:'moment-real',name:'真实时刻',date:'2026-10-04',story:'时刻正文'}]))");go(p,9,'?id=book-state&page=page-state');p.locator('#excerpt').fill('在时刻模板里仍保留的正文');switch(p,'重要时刻');p.wait_for_url('**/m08-p11.html*');switch(p,'日记摘录');p.wait_for_url('**/m08-p09.html*');expect(p.locator('#page-title')).to_have_value('共同正文');switch(p,'重要时刻');p.wait_for_url('**/m08-p11.html*');p.locator('.select-action').click();p.get_by_role('button',name='真实时刻',exact=True).click();expect(p.locator('dialog[open]')).to_have_count(0);switch(p,'日记摘录');p.wait_for_url('**/m08-p09.html*');expect(p.locator('#excerpt')).to_have_value('在时刻模板里仍保留的正文');switch(p,'重要时刻');p.wait_for_url('**/m08-p11.html*');expect(p.locator('.moment')).to_have_value('真实时刻');token=p.evaluate("new URLSearchParams(location.search).get('draft')");go(p,9,'?id=other-book&page=page-state&draft='+token);expect(p.locator('#excerpt')).to_have_value('SOURCE-SECRET');assert value(p)[1]['pages'][0].get('body') is None

def work_pet_roundtrip(p):
 seed(p,books=[fixture()],records=records());p.evaluate("()=>{localStorage.setItem('dujia-prototype-works',JSON.stringify([{id:'actual-work',name:'真实工坊书页',status:'ready',type:'comic',sourceIds:[],sourceKind:'free',story:'作品正文',createdAt:1791158400000}]));localStorage.setItem('dujia-prototype-pet',JSON.stringify({id:'pet-draft',status:'active',logs:[{id:'note-real',type:'note',text:'实际宠物成长',date:'2026-10-04'}]}));}");go(p,9,'?id=book-state&page=page-state');p.locator('#excerpt').fill('五种模板共用的独立文字');switch(p,'工坊作品');p.wait_for_url('**/m08-p12.html*');p.locator('[data-action="换内容"]').click();p.get_by_role('button',name='真实工坊书页',exact=True).click();expect(p.locator('dialog[open]')).to_have_count(0);switch(p,'宠物成长');p.wait_for_url('**/m08-p12.html*');p.locator('[data-action="换内容"]').click();p.get_by_role('button',name='实际宠物成长',exact=True).click();expect(p.locator('dialog[open]')).to_have_count(0);switch(p,'工坊作品');p.wait_for_url('**/m08-p12.html*');expect(p.locator('.pet-name')).to_have_text('真实工坊书页');expect(p.locator('.caption')).to_have_value('五种模板共用的独立文字');p.locator('.done').click();p.wait_for_url('**/m08-p13.html*');saved=value(p)[0]['pages'][0];assert saved['source']==dict(kind='work',id='actual-work') and saved['body']=='五种模板共用的独立文字' and len(value(p)[0]['pages'])==1

rows=[]
with sync_playwright() as pw:
 b=pw.chromium.launch(headless=True,executable_path=r'C:\Program Files\Google\Chrome\Application\chrome.exe')
 for name,run in {'diary-photo-diary-preserves-full-page-id':diary_roundtrip,'photo-crop-stickers-roundtrip-save-retry':photo_roundtrip,'stash-failure-and-resumed-dirty-discard':failed_stash_discard,'resumed-page-conflict-preserves-local-and-peer':conflict,'new-stable-page-and-deleted-page-route':new_page_and_stale_route,'specialist-source-roundtrip-and-book-isolation':specialist_roundtrip_and_isolation,'work-pet-template-source-roundtrip':work_pet_roundtrip}.items():
  c=b.new_context(viewport={'width':390,'height':844});p=c.new_page();p.set_default_timeout(5000);errors=[];p.on('pageerror',lambda e:errors.append(str(e)))
  try:run(p);assert not errors,errors;row=dict(case=name,passed=True)
  except Exception:row=dict(case=name,passed=False,failure=traceback.format_exc()[-2200:])
  row.update(errors=errors,url=p.url);rows.append(row);print(('PASS ' if row['passed'] else 'FAIL ')+name,flush=True);c.close()
 b.close()
OUT.mkdir(parents=True,exist_ok=True);(OUT/'book-editor-draft-results.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
raise SystemExit(0 if all(v['passed'] for v in rows) else 1)
